 /* ============================================================
    LUMA — Main JS
    ============================================================ */

 // ── Cart state ────────────────────────────────────────────────
 const cart = { count: 0 };
 const cartCountEl  = document.getElementById('cart-count');
 const cartLabelEl  = document.getElementById('cart-label');
 const srStatus     = document.getElementById('sr-status');

 function announce(msg) {
   srStatus.textContent = '';
   // Force repaint so screen readers pick up the change
   requestAnimationFrame(() => { srStatus.textContent = msg; });
 }

 function updateCartUI() {
   cartCountEl.textContent = cart.count;
   cartCountEl.hidden = cart.count === 0;
   cartLabelEl.textContent = `Cart, ${cart.count} item${cart.count !== 1 ? 's' : ''}`;
 }

 // ── Add to cart ───────────────────────────────────────────────
 document.querySelectorAll('.add-to-cart-btn').forEach(btn => {
   btn.addEventListener('click', () => {
     cart.count++;
     updateCartUI();
     const productName = btn.dataset.product || 'item';
     announce(`${productName} added to cart. Cart now has ${cart.count} item${cart.count !== 1 ? 's' : ''}.`);
   });
 });

 // ── Announcement bar dismiss ──────────────────────────────────
 const announcementBar = document.getElementById('announcement-bar');
 const dismissBtn = document.getElementById('dismiss-announcement');
 if (dismissBtn && announcementBar) {
   dismissBtn.addEventListener('click', () => {
     announcementBar.hidden = true;
   });
 }

 // ── Mobile nav toggle ─────────────────────────────────────────
 const mobileToggle = document.getElementById('mobile-menu-toggle');
 const mobileNav    = document.getElementById('mobile-nav');

 if (mobileToggle && mobileNav) {
   mobileToggle.addEventListener('click', () => {
     const isOpen = mobileNav.classList.toggle('open');
     mobileToggle.setAttribute('aria-expanded', String(isOpen));
   });

   // Close on Escape
   document.addEventListener('keydown', e => {
     if (e.key === 'Escape' && mobileNav.classList.contains('open')) {
       mobileNav.classList.remove('open');
       mobileToggle.setAttribute('aria-expanded', 'false');
       mobileToggle.focus();
     }
   });
 }

 // ── Category dropdown ────────────────────────────────────────
 document.querySelectorAll('.nav-dropdown-toggle').forEach(toggle => {
   const dropdown = toggle.nextElementSibling;
   if (!dropdown) return;

   toggle.addEventListener('click', () => {
     const isOpen = !dropdown.hidden;
     dropdown.hidden = isOpen;
     toggle.setAttribute('aria-expanded', String(!isOpen));
   });

   // Close on Escape
   toggle.addEventListener('keydown', e => {
     if (e.key === 'Escape' && !dropdown.hidden) {
       dropdown.hidden = true;
       toggle.setAttribute('aria-expanded', 'false');
       toggle.focus();
     }
   });

   // Close when focus leaves the nav item
   const navItem = toggle.closest('.nav-item');
   if (navItem) {
     navItem.addEventListener('focusout', e => {
       if (!navItem.contains(e.relatedTarget)) {
         dropdown.hidden = true;
         toggle.setAttribute('aria-expanded', 'false');
       }
     });
   }
 });

 // ── Newsletter form ───────────────────────────────────────────
 const newsletterForm = document.getElementById('newsletter-form');
 const newsletterStatus = document.getElementById('newsletter-status');

 if (newsletterForm) {
   newsletterForm.addEventListener('submit', e => {
     e.preventDefault();
     const email = newsletterForm.querySelector('input[type="email"]').value;
     if (email) {
       newsletterStatus.textContent = '✓ You\'re subscribed! Check your inbox for a welcome email.';
       newsletterForm.reset();
       announce('Newsletter subscription confirmed.');
     }
   });
 }

 // ── Wishlist toggle ───────────────────────────────────────────
 document.querySelectorAll('.wishlist-btn').forEach(btn => {
   btn.addEventListener('click', e => {
     e.stopPropagation();
     const pressed = btn.getAttribute('aria-pressed') === 'true';
     btn.setAttribute('aria-pressed', String(!pressed));
     const name = btn.dataset.product || 'item';
     btn.querySelector('svg').style.fill = !pressed ? 'currentColor' : 'none';
     announce(!pressed ? `${name} saved to wishlist` : `${name} removed from wishlist`);
   });
 });

 // ── Countdown timers ─────────────────────────────────────────
 document.querySelectorAll('[data-countdown]').forEach(el => {
   let remaining = parseInt(el.dataset.countdown, 10); // seconds

   function fmt(s) {
     const h = Math.floor(s / 3600).toString().padStart(2, '0');
     const m = Math.floor((s % 3600) / 60).toString().padStart(2, '0');
     const sec = (s % 60).toString().padStart(2, '0');
     return `${h}:${m}:${sec}`;
   }

   el.textContent = fmt(remaining);
   const interval = setInterval(() => {
     remaining = Math.max(0, remaining - 1);
     el.textContent = fmt(remaining);
     if (remaining === 0) clearInterval(interval);
   }, 1000);
 });

