 /* ============================================================
    LUMA — Dark Ecommerce Theme
    ============================================================ */

 /* ── Reset & base ─────────────────────────────────────────── */
 *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

 :root {
   --bg-base:        #0d0d0f;
   --bg-surface:     #18181c;
   --bg-card:        #1e1e24;
   --bg-card-hover:  #26262e;
   --bg-overlay:     #28282f;
   --border:         #2e2e38;
   --border-focus:   #6c63ff;

   --text-primary:   #f0f0f5;
   --text-secondary: #b8b8cc;
   --text-muted:     #9898b4;
   --text-on-accent: #ffffff;

   /* Accent: light shade for text/links; dark shade for filled button backgrounds */
   --accent-primary: #9088ff;   /* text, links, borders — passes 4.5:1 on dark bg */
   --accent-hover:   #a098ff;
   --accent-btn:     #4840c8;   /* filled button bg — passes 4.5:1 with white text */
   --accent-btn-hover: #5a52d4;
   --accent-press:   #3a34a8;
   --border-focus:   #9088ff;

   /* Deal red: light shade for text/badges; dark shade for CTA button */
   --deal-badge:     #ff8098;   /* badge text / border — passes on dark bg */
   --deal-badge-bg:  rgba(255, 128, 152, 0.15);
   --deal-btn:       #c02040;   /* CTA button bg — passes 4.5:1 with white text */
   --deal-btn-hover: #a81835;
   --new-badge:      #00d4aa;
   --new-badge-bg:   rgba(0, 212, 170, 0.15);

   --radius-sm:  6px;
   --radius-md:  10px;
   --radius-lg:  16px;
   --radius-xl:  24px;

   --shadow-card: 0 2px 12px rgba(0,0,0,.4);
   --shadow-raise: 0 8px 32px rgba(0,0,0,.55);

   --font-sans: 'Inter', 'Segoe UI', system-ui, sans-serif;
   --font-display: 'Inter', 'Segoe UI', system-ui, sans-serif;

   --header-h: 64px;
   --transition: 180ms ease;
 }

 html { scroll-behavior: smooth; }

 body {
   font-family: var(--font-sans);
   background: var(--bg-base);
   color: var(--text-primary);
   line-height: 1.6;
   min-height: 100vh;
   -webkit-font-smoothing: antialiased;
 }

 img { display: block; max-width: 100%; }
 a { color: inherit; text-decoration: none; }
 ul { list-style: none; }
 button { font: inherit; cursor: pointer; border: none; background: none; }

 /* ── Skip link ────────────────────────────────────────────── */
 .skip-link {
   position: absolute;
