   clip: rect(0 0 0 0);
   clip-path: inset(50%);
   height: 1px;
   overflow: hidden;
   width: 1px;
 }
 .skip-link:focus { clip: auto; clip-path: none; height: auto; width: auto; }

 /* ── Focus ring ───────────────────────────────────────────── */
 :focus-visible {
   outline: 2px solid var(--border-focus);
