const { chromium } = require('playwright');
const axe = require('axe-core');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('file://' + path.resolve('index.html'));
  await page.addScriptTag({ content: axe.source });
  const results = await page.evaluate(() => axe.run({
    runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice'] }
  }));
  await browser.close();

  results.violations.forEach(v => {
    console.log('[VIOLATION]', v.id, '—', v.description);
    v.nodes.forEach(n => console.log('  ', n.html.slice(0,120)));
  });
  results.incomplete.forEach(v => {
    console.log('[INCOMPLETE]', v.id, '(impact:'+v.impact+') —', v.description);
    v.nodes.forEach(n => {
      console.log('  target:', JSON.stringify(n.target));
      console.log('  html:', n.html.slice(0,100));
    });
  });

  console.log('\nViolations:', results.violations.length, '| Incomplete:', results.incomplete.length);
})();
